import { chmodSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

import Database from 'better-sqlite3';
import { and, eq, inArray, isNotNull } from 'drizzle-orm';
import { drizzle, type BetterSQLite3Database } from 'drizzle-orm/better-sqlite3';

// Bundled via electron-vite's `?raw` asset import so the packaged Runtime never reads migration
// SQL from disk (see sql-raw.d.ts for the ambient module declaration this relies on). Generated by
// `bunx drizzle-kit generate` from `schema.ts`; keep these in sync by regenerating rather than
// hand-editing migration files.
import baselineMigrationSql from './migrations/0000_silly_groot.sql?raw';
import sessionArchiveMigrationSql from './migrations/0001_slim_marvel_boy.sql?raw';
import sessionStateVersionMigrationSql from './migrations/0002_complex_ironclad.sql?raw';
import sessionTitleModeMigrationSql from './migrations/0003_pretty_ezekiel.sql?raw';
import projectOrderMigrationSql from './migrations/0004_wonderful_gladiator.sql?raw';
import sessionAttentionMigrationSql from './migrations/0005_dazzling_the_professor.sql?raw';
import * as schema from './schema';
import { sessions, terminals } from './schema';
import { shutdownOutcome, type ShutdownReason } from '../session-policy';

/**
 * Single source of truth for the schema version. Bumped whenever the generated DDL changes shape.
 * Schema 7 is the preservation floor: older pre-release databases may still be rebuilt, while 7+
 * must advance through the incremental migration list below without losing metadata. Recorded in
 * two places that must stay in sync: the SQLite `user_version`
 * pragma (managed below) and the `schemaVersion` app-state row (written by `bootstrap.ts`).
 */
export const CURRENT_SCHEMA_VERSION = 11;

const PRESERVED_SCHEMA_VERSION = 7;

export { DEFAULT_LAYOUT_VERSION } from './schema';

export type CaxriDrizzleDatabase = BetterSQLite3Database<typeof schema>;

function restrictPath(path: string, mode: number): void {
    try {
        chmodSync(path, mode);
    } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
    }
}

function runGeneratedSql(database: Database.Database, sql: string): void {
    database.exec(sql.replaceAll('--> statement-breakpoint', ''));
}

function installCurrentSchema(database: Database.Database): void {
    for (const sql of [
        baselineMigrationSql,
        sessionArchiveMigrationSql,
        sessionStateVersionMigrationSql,
        sessionTitleModeMigrationSql,
        projectOrderMigrationSql,
        sessionAttentionMigrationSql,
    ])
        runGeneratedSql(database, sql);
}

const preservingMigrations = [
    { version: 8, sql: sessionStateVersionMigrationSql },
    { version: 9, sql: sessionTitleModeMigrationSql },
    { version: 10, sql: projectOrderMigrationSql },
    { version: 11, sql: sessionAttentionMigrationSql },
] as const;

/** Preserves the v9 Sidebar order, which was defined by `created_at, id`, as explicit indexes. */
function backfillProjectOrder(database: Database.Database): void {
    const legacyProjects = database
        .prepare('SELECT id FROM projects ORDER BY created_at, id')
        .all() as Array<{ id: string }>;
    const updateOrder = database.prepare('UPDATE projects SET order_index = ? WHERE id = ?');
    for (const [orderIndex, project] of legacyProjects.entries())
        updateOrder.run(orderIndex, project.id);
}

function migratePreservingData(database: Database.Database, version: number): void {
    for (const migration of preservingMigrations)
        if (migration.version > version) runGeneratedSql(database, migration.sql);
    if (version < 10) backfillProjectOrder(database);
}

function initializeSchema(database: Database.Database): void {
    const version = database.pragma('user_version', { simple: true }) as number;
    if (version > CURRENT_SCHEMA_VERSION) {
        throw new Error(
            `Database uses newer schema version ${version}; Caxri supports ${CURRENT_SCHEMA_VERSION}`,
        );
    }
    database.transaction(() => {
        if (version > 0 && version < PRESERVED_SCHEMA_VERSION) {
            /** Pre-release metadata can be rebuilt; Project directories and user files are never touched. */
            database.exec(`
                DROP TABLE IF EXISTS terminal_snapshots;
                DROP TABLE IF EXISTS session_state;
                DROP TABLE IF EXISTS terminals;
                DROP TABLE IF EXISTS sessions;
                DROP TABLE IF EXISTS projects;
                DROP TABLE IF EXISTS app_state;
            `);
        }
        if (version === 0 || (version > 0 && version < PRESERVED_SCHEMA_VERSION))
            installCurrentSchema(database);
        else if (version < CURRENT_SCHEMA_VERSION) migratePreservingData(database, version);
        database.pragma(`user_version = ${CURRENT_SCHEMA_VERSION}`);
    })();
}

/**
 * Bulk-marks Terminals that were still alive as of `reason` (see {@link ShutdownReason}) with the
 * resulting Terminal/Session state pair decided by `session-policy.ts`'s {@link shutdownOutcome}.
 * This module owns only the query/update mechanics; which states apply is a domain decision.
 * Exported as `markShutdown` for both the recovery path at {@link openDatabase} (always `unclean`)
 * and `./index.ts`'s `CaxriDb.markShutdown` (orderly/terminate, chosen by the caller).
 */
export function markShutdown(db: CaxriDrizzleDatabase, now: number, reason: ShutdownReason): void {
    const { liveProcessStates, terminalProcessState, primaryAgentSessionState } =
        shutdownOutcome(reason);
    db.update(terminals)
        .set({ lastProcessState: terminalProcessState, updatedAt: now })
        .where(inArray(terminals.lastProcessState, liveProcessStates))
        .run();
    db.update(sessions)
        .set({ lastActivityState: primaryAgentSessionState })
        .where(
            inArray(
                sessions.primaryAgentTerminalId,
                db
                    .select({ id: terminals.id })
                    .from(terminals)
                    .where(
                        and(
                            isNotNull(terminals.provider),
                            eq(terminals.lastProcessState, terminalProcessState),
                        ),
                    ),
            ),
        )
        .run();
}

export interface OpenedDatabase {
    /** Raw better-sqlite3 handle; still needed for pragmas and integration tests that inspect
        `table_info`/`user_version` directly. */
    database: Database.Database;
    /** Drizzle query-builder instance bound to the same connection and to `./schema`. */
    db: CaxriDrizzleDatabase;
}

/**
 * Opens (creating if needed) the Caxri SQLite database: restricts the owning directory and file to
 * the current user, enables WAL/foreign-keys/busy-timeout, runs schema initialization, and recovers
 * from any unclean previous shutdown.
 */
export function openDatabase(path: string): OpenedDatabase {
    if (path !== ':memory:') {
        mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
        /** Electron owns this userData directory, so restricting it also protects adjacent Caxri configuration and logs. */
        restrictPath(dirname(path), 0o700);
    }
    const database = new Database(path);
    try {
        if (path !== ':memory:') restrictPath(path, 0o600);
        database.pragma('journal_mode = WAL');
        database.pragma('foreign_keys = ON');
        database.pragma('busy_timeout = 5000');
        initializeSchema(database);
        const db = drizzle(database, { schema });
        markShutdown(db, Date.now(), 'unclean');
        if (path !== ':memory:') {
            restrictPath(`${path}-wal`, 0o600);
            restrictPath(`${path}-shm`, 0o600);
        }
        return { database, db };
    } catch (error) {
        database.close();
        throw error;
    }
}
